// Icône seule de la marque, sans le mot-symbole : le rail tablette replié
// (72 px de large) est trop étroit pour le logo complet. Même tracé que
// LogoSVG, recadré sur la seule icône. Monochrome, couleur héritée.
const IconeSVG = ({ className = "h-7 w-7" }) => (
    <svg className={className} viewBox="24.39 10.60 82.14 102.23" fill="currentColor"
         xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <polygon points="31.88 47.79 31.9 103.45 36.78 103.42 36.79 71.56 52.8 61.35 52.8 109.05 47.23 109.06 47.23 71.58 42.28 74.69 42.28 109.08 26.39 109.08 26.39 44.54 74.12 12.6 74.15 45.36 85.04 50.98 85 80.55 79.54 85.68 79.54 54.54 65.17 47.08 65.15 93.56 59.59 93.61 59.59 37.96 68.58 42.55 68.54 23.33 31.88 47.79"/>
        <path d="M60.34,101.32c-.66-.74-1.19-1.51-.52-2.42l5.88.02,3.22,4.06,20.14-19,15.35-14.47.12,7.63-23.38,21.96-12.35,11.73-8.45-9.51Z"/>
    </svg>
);


const CustomSelect = ({ value, onChange, options, className, disabled = false, ['aria-label']: ariaLabel }) => {
    const [isOpen, setIsOpen] = useState(false);
    const selectRef = useRef(null);
    
    const selectedOption = options.find(o => String(o.value) === String(value)) || options[0];

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (selectRef.current && !selectRef.current.contains(event.target)) setIsOpen(false);
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div ref={selectRef} className={`relative ${className || ''}`}>
            <button type="button" disabled={disabled} onClick={() => !disabled && setIsOpen(!isOpen)}
                aria-label={ariaLabel}
                aria-haspopup="listbox"
                aria-expanded={isOpen}
                className={`w-full text-left px-4 py-3 border rounded-xl text-sm font-semibold transition-all focus:outline-none flex justify-between items-center ${disabled ? 'bg-neutral-100 text-neutral-500 border-neutral-200 cursor-not-allowed' : isOpen ? 'border-brand-500 bg-white ring-4 ring-brand-500/10 text-brand-700' : 'bg-neutral-50 border-neutral-200 text-neutral-800 hover:border-neutral-300 hover:bg-white'}`}>
                <span className="truncate">{selectedOption ? selectedOption.label : 'Sélectionner...'}</span>
                <i className={`fa-solid fa-chevron-down text-[10px] transition-transform duration-200 ${isOpen ? 'rotate-180 text-brand-500' : 'text-neutral-500'}`}></i>
            </button>
            {isOpen && !disabled && (
                // picker-popover : sur téléphone (< 480px) ce panneau devient une
                // page de sélection plein écran — voir le bloc PWA MOBILE dans
                // index.html. Au-dessus, il reste le menu flottant habituel.
                <div role="listbox" className="picker-popover absolute z-[100] w-full mt-2 bg-white border border-neutral-100 rounded-xl shadow-floating overflow-hidden animate-fade-in origin-top">
                    <div className="picker-mobile-header">
                        <button
                            type="button"
                            onClick={() => setIsOpen(false)}
                            className="picker-mobile-back"
                            aria-label="Fermer la liste"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                        <p className="min-w-0 flex-1 text-sm font-bold text-neutral-900 truncate">
                            {ariaLabel || 'Choisir une option'}
                        </p>
                    </div>
                    <div className="picker-results max-h-60 overflow-y-auto">
                        {options.map((opt) => (
                            <button key={opt.value} type="button" onClick={() => { onChange({ target: { value: opt.value }}); setIsOpen(false); }}
                                role="option"
                                aria-selected={String(value) === String(opt.value)}
                                className={`w-full text-left px-4 py-3 text-sm transition-colors flex items-center justify-between ${String(value) === String(opt.value) ? 'bg-brand-50 text-brand-700 font-bold' : 'text-neutral-700 font-medium hover:bg-neutral-50 hover:text-neutral-900'}`}>
                                <span>{opt.label}</span>
                                {String(value) === String(opt.value) && <i className="fa-solid fa-check text-brand-600 text-xs"></i>}
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

// V2 UI/UX — Sélecteur contextuel de client pour le devis.
// Le champ reste compatible avec l'ancien modèle texte (clientName), tout en
// proposant la recherche, le clavier et la création contextuelle sans quitter
// l'espace de chiffrage.
function ClientCombobox({
    value = '',
    clientId = null,
    clients = [],
    onChange,
    onSelectClient,
    onRequestCreate,
    disabled = false,
    // Audit UX (2026-09-01) — l'audit demandait, en plus du message d'erreur,
    // d'agir sur le CHAMP fautif : bordure rouge, focus, mention « requis ».
    // C'était fait sur l'ancien formulaire d'enregistrement (`clientNameError`)
    // mais pas sur ce champ-ci, celui que l'éditeur utilise réellement :
    // l'utilisateur recevait un message rouge sans savoir où corriger.
    enErreur = false
}) {
    const [query, setQuery] = useState(value || '');
    const [isOpen, setIsOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(0);
    const rootRef = useRef(null);
    const mobileSearchRef = useRef(null);
    const inputRef = useRef(null);

    // Le focus est posé quand le drapeau PASSE à vrai, pas à chaque rendu :
    // sinon le champ le reprendrait pendant que l'utilisateur corrige ailleurs.
    const erreurPrecedente = useRef(false);
    // `erreurAffichee` retombe dès la première frappe : le parent, lui, ne voit
    // le nom qu'au moment où il est validé (sélection ou sortie du champ), donc
    // s'en remettre à lui laisserait la bordure rouge pendant toute la saisie —
    // le champ continuerait à crier une faute que l'utilisateur est en train de
    // corriger. Le parent reste la source de vérité pour la RE-signaler au
    // prochain enregistrement.
    const [erreurAffichee, setErreurAffichee] = useState(false);
    useEffect(() => {
        if (enErreur && !erreurPrecedente.current && inputRef.current) {
            setErreurAffichee(true);
            inputRef.current.focus();
            inputRef.current.select?.();
        }
        if (!enErreur) setErreurAffichee(false);
        erreurPrecedente.current = enErreur;
    }, [enErreur]);

    useEffect(() => {
        setQuery(value || '');
    }, [value]);

    // Sur téléphone la liste s'ouvre en page plein écran : le champ de
    // recherche de cette page doit prendre le focus, sinon Safari le garde sur
    // la puce restée derrière le panneau et déclenche un zoom parasite.
    // Même mécanique que SolutionCombobox.
    useEffect(() => {
        if (!isOpen || typeof window === 'undefined' || !window.matchMedia('(max-width: 480px)').matches) return;
        const timer = window.setTimeout(() => mobileSearchRef.current?.focus({ preventScroll: true }), 30);
        return () => window.clearTimeout(timer);
    }, [isOpen]);

    // Audit UX (2026-08-31) — le nom du client disparaissait de son champ dès
    // le premier clic ailleurs dans l'éditeur APRÈS avoir été confirmé, alors
    // que l'état du devis, lui, le conservait parfaitement (vérifié : devis
    // enregistré et brouillon portaient bien « SARL Diarra Construction »
    // pendant que le champ affichait du vide). L'utilisateur voyait son client
    // s'effacer juste après l'avoir saisi : soit il le retapait, soit il
    // doutait du reste.
    //
    // Cause : `value` était lu dans la fermeture du PREMIER rendu. Le listener
    // mousedown est posé par un useEffect à dépendances [] — il ne voit donc
    // jamais que la version de restoreCommittedValue créée au montage, quand
    // le devis n'avait pas encore de client (value = ''). Chaque restauration
    // réécrivait donc cette chaîne vide d'origine.
    //
    // Le fix P3 du 30/08 avait introduit `latestRef` précisément pour tenir
    // ces valeurs à jour dans le listener, mais restoreCommittedValue était
    // resté en dehors. On le fait lire le ref : la restauration rend la valeur
    // réellement committée, pas celle d'il y a dix minutes.
    const restoreCommittedValue = () => setQuery((latestRef.current?.value ?? value) || '');

    // Fix P3 (2026-08-30) — cliquer AILLEURS dans l'éditeur (ex. la barre de
    // recherche d'ouvrage, pour ajouter une ligne) pendant qu'un nom de
    // client venait d'être tapé faisait disparaître ce texte sans avertir :
    // `restoreCommittedValue()` écrasait inconditionnellement la saisie en
    // cours dès qu'un mousedown sortait de `rootRef`, même avec une
    // suggestion "Créer «X»" visible et non encore confirmée. Observé 3 fois
    // pendant la campagne de test du 2026-08-29/30 (obligeant à retaper le
    // nom à chaque fois). Ce ref garde les dernières valeurs pertinentes à
    // jour sans réabonner le listener à chaque frappe (il reste monté une
    // seule fois, comme avant).
    const latestRef = useRef({ query, value, clients, onChange, onSelectClient });
    latestRef.current = { query, value, clients, onChange, onSelectClient };

    // Audit du 2026-09-02 — la validation ci-dessous n'était accrochée qu'au
    // `mousedown` hors du champ. Quitter le champ AU CLAVIER (Tab) ne la
    // déclenchait donc pas : le nom tapé restait affiché à l'écran mais
    // n'atteignait jamais le devis, et l'enregistrement répondait « Nom du
    // client manquant » devant un champ qui montrait pourtant le nom.
    // Reproduit en tapant « Client Témoin » puis Tab. La logique est extraite
    // ici pour servir les deux sorties — souris et clavier — sans divergence.
    const committerSaisieLibre = React.useCallback(() => {
        const { query: q, value: committedValue, clients: cs, onChange: change, onSelectClient: selectClientFn } = latestRef.current;
        const trimmed = q.trim();
        const committedTrimmed = (committedValue || '').trim();
        const matched = cs.find((c) => normalizeSearchText(c.name) === normalizeSearchText(trimmed));
        if (trimmed && trimmed !== committedTrimmed && matched) {
            selectClientFn?.(matched);
        } else if (trimmed && trimmed !== committedTrimmed) {
            change?.({ clientName: trimmed, clientId: null });
        } else {
            setQuery((latestRef.current?.value ?? committedValue) || '');
        }
    }, []);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (rootRef.current && !rootRef.current.contains(event.target)) {
                const { query: q, value: committedValue, clients: cs, onChange: change, onSelectClient: selectClientFn } = latestRef.current;
                const trimmed = q.trim();
                const committedTrimmed = (committedValue || '').trim();
                const matched = cs.find((c) => normalizeSearchText(c.name) === normalizeSearchText(trimmed));
                if (trimmed && trimmed !== committedTrimmed && matched) {
                    // La saisie correspond exactement à un client déjà connu
                    // (ex. créé lors d'une frappe précédente) : le sélectionner
                    // pour de bon plutôt que de silencieusement l'ignorer.
                    selectClientFn?.(matched);
                } else if (trimmed && trimmed !== committedTrimmed) {
                    // Saisie non confirmée mais non vide, sans correspondance
                    // connue : la committer en texte libre (le composant reste
                    // "compatible avec l'ancien modèle texte", voir le
                    // commentaire en tête de fichier) plutôt que la faire
                    // disparaître silencieusement.
                    change?.({ clientName: trimmed, clientId: null });
                } else {
                    restoreCommittedValue();
                }
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const normalizedQuery = normalizeSearchText(query.trim());
    const filteredClients = clients.filter(client => {
        if (!normalizedQuery) return true;
        return [client.name, client.contactPerson, client.phone, client.email, client.id]
            .filter(Boolean)
            .some(valueToSearch => normalizeSearchText(valueToSearch).includes(normalizedQuery));
    }).slice(0, 8);
    const exactClient = clients.find(client => normalizeSearchText(client.name) === normalizedQuery);
    const canCreate = Boolean(normalizedQuery && !exactClient);
    const optionCount = filteredClients.length + (canCreate ? 1 : 0);

    useEffect(() => {
        setHighlightedIndex(0);
    }, [normalizedQuery]);

    const selectClient = (client) => {
        setQuery(client.name || '');
        setIsOpen(false);
        onSelectClient?.(client);
    };

    const requestCreate = () => {
        const initialName = query.trim();
        if (!initialName && !onRequestCreate) return;
        setIsOpen(false);
        onRequestCreate?.(initialName);
    };

    const handleKeyDown = (event) => {
        if (event.key === 'Escape') {
            event.stopPropagation();
            restoreCommittedValue();
            setIsOpen(false);
            return;
        }
        if (!isOpen && ['ArrowDown', 'Enter'].includes(event.key)) {
            event.preventDefault();
            setIsOpen(true);
            return;
        }
        if (!isOpen) return;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlightedIndex(index => Math.min(index + 1, Math.max(0, optionCount - 1)));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlightedIndex(index => Math.max(0, index - 1));
        } else if (event.key === 'Enter') {
            event.preventDefault();
            if (highlightedIndex < filteredClients.length) selectClient(filteredClients[highlightedIndex]);
            else if (canCreate) requestCreate();
        }
    };

    return (
        <div ref={rootRef} className="relative flex-1 min-w-0">
            <div className={`relative ${isOpen ? 'z-[101]' : ''}`}>
                <i className="fa-solid fa-user absolute left-3 sm:left-3.5 top-1/2 -translate-y-1/2 text-neutral-500 text-[11px] pointer-events-none" aria-hidden="true"></i>
                <input
                    ref={inputRef}
                    type="text"
                    value={query}
                    disabled={disabled}
                    // Audit UX (2026-08-31) — `onFocus` ouvrait la liste : en
                    // navigation clavier, chaque passage sur ce champ déployait un
                    // panneau qui recouvrait le titre du lot et une partie du
                    // tableau. Le clic et la frappe suffisent à exprimer
                    // l'intention d'ouvrir ; traverser le champ ne l'exprime pas.
                    onClick={() => setIsOpen(true)}
                    onChange={(event) => {
                        const nextQuery = event.target.value;
                        setQuery(nextQuery);
                        setIsOpen(true);
                        setErreurAffichee(false);
                    }}
                    onKeyDown={handleKeyDown}
                    // Sortie AU CLAVIER (Tab) — voir le commentaire de
                    // committerSaisieLibre. Le report d'un cycle laisse un clic
                    // sur une option de la liste se produire d'abord : sans lui,
                    // le blur validerait le texte tapé et annulerait la
                    // sélection que l'utilisateur vient de faire à la souris.
                    onBlur={() => {
                        // On ne renonce que si le focus part vers la LISTE de
                        // suggestions : c'est le seul cas où l'utilisateur est
                        // encore en train de choisir. Un premier jet excluait
                        // tout le composant, or Tab depuis le champ atterrit sur
                        // la croix « Effacer » qui en fait partie — la saisie
                        // n'était donc toujours pas validée au clavier.
                        setTimeout(() => {
                            const actif = document.activeElement;
                            const liste = document.getElementById('quote-client-listbox');
                            if (actif && liste && liste.contains(actif)) return;
                            committerSaisieLibre();
                            setIsOpen(false);
                        }, 0);
                    }}
                    placeholder="Client"
                    // Puce compacte sous sm: (rounded-full, plus étroite, placeholder
                    // court) au lieu de la barre de recherche pleine largeur — même
                    // input, mêmes onChange/onFocus, seule l'habillage change.
                    className={`w-full bg-neutral-50 hover:bg-white focus:bg-white border rounded-xl sm:rounded-lg pl-9 sm:pl-10 pr-9 sm:pr-8 py-2.5 sm:py-1.5 text-xs font-bold text-neutral-900 placeholder-neutral-500 outline-none transition-all truncate ${erreurAffichee ? 'border-red-500 ring-2 ring-red-500/25 bg-red-50/40' : isOpen ? 'border-brand-500 ring-2 ring-brand-500/10 bg-brand-50/50' : 'border-neutral-200'} ${disabled ? 'opacity-60 cursor-not-allowed' : ''}`}
                    aria-label={erreurAffichee ? 'Client du devis — requis' : 'Client du devis'}
                    aria-invalid={erreurAffichee || undefined}
                    aria-autocomplete="list"
                    aria-controls="quote-client-listbox"
                    aria-expanded={isOpen}
                    aria-haspopup="listbox"
                    role="combobox"
                />
                {query && !disabled && (
                    <button
                        type="button"
                        onClick={() => { setQuery(''); onChange?.({ clientName: '', clientId: null }); setIsOpen(true); }}
                        className="champ-effacer absolute right-2 top-1/2 -translate-y-1/2 text-neutral-500 hover:text-neutral-700 w-5 h-5 rounded-full hover:bg-neutral-100"
                        aria-label="Effacer le client"
                    >
                        <i className="fa-solid fa-xmark text-[10px]"></i>
                    </button>
                )}
                {/* Chevron de rangée : signale que taper ouvre une page de
                    sélection. Masqué quand la croix d'effacement occupe la place. */}
                {!query && (
                    // sm:hidden porté par le <span>, jamais par le <i> : Font Awesome
                    // (chargé APRÈS tailwind.css) impose `display: inline-block` à
                    // .fa-solid et gagne à spécificité égale — posé sur l'icône,
                    // `hidden` resterait sans effet et le chevron s'afficherait aussi
                    // sur desktop. Même piège que .btn-icon / .btn-primary.
                    <span className="sm:hidden absolute right-3 top-1/2 -translate-y-1/2 text-neutral-300 text-[10px] pointer-events-none" aria-hidden="true">
                        <i className="fa-solid fa-chevron-right"></i>
                    </span>
                )}
            </div>

            {isOpen && !disabled && (
                <div id="quote-client-listbox" role="listbox" className="picker-popover absolute left-0 right-0 top-full mt-1.5 bg-white border border-neutral-200 rounded-xl shadow-floating overflow-hidden z-[100] animate-fade-in">
                    <div className="picker-mobile-header">
                        <button
                            type="button"
                            onClick={() => { restoreCommittedValue(); setIsOpen(false); }}
                            className="picker-mobile-back"
                            aria-label="Retour au devis"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                        <div className="min-w-0 flex-1">
                            <p className="text-sm font-bold text-neutral-900 truncate">Choisir un client</p>
                            <p className="text-[11px] text-neutral-500 truncate">Recherchez une fiche ou créez-en une</p>
                        </div>
                        {query && (
                            <button
                                type="button"
                                onClick={() => setQuery('')}
                                className="picker-mobile-clear"
                                aria-label="Effacer la recherche"
                            >
                                Effacer
                            </button>
                        )}
                    </div>
                    <div className="picker-mobile-search">
                        <i className="fa-solid fa-magnifying-glass"></i>
                        <input
                            ref={mobileSearchRef}
                            type="text"
                            value={query}
                            onChange={(event) => { setQuery(event.target.value); setIsOpen(true); }}
                            onKeyDown={handleKeyDown}
                            placeholder="Rechercher un client…"
                            aria-label="Rechercher un client"
                        />
                    </div>
                    <div className="picker-popover-label px-3 pt-2.5 pb-1.5 text-[10px] font-bold uppercase tracking-wider text-neutral-500">
                        {normalizedQuery ? 'Résultats clients' : 'Clients récents'}
                    </div>
                    <div className="picker-results max-h-56 overflow-y-auto custom-scroll p-1.5">
                        {filteredClients.map((client, index) => (
                            <button
                                key={client.id || client.name}
                                type="button"
                                role="option"
                                aria-selected={String(clientId) === String(client.id)}
                                onMouseEnter={() => setHighlightedIndex(index)}
                                onClick={() => selectClient(client)}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 transition-colors ${highlightedIndex === index ? 'bg-brand-50 text-brand-900' : 'text-neutral-700 hover:bg-neutral-50'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-neutral-100 text-neutral-500 flex items-center justify-center shrink-0">
                                    <i className="fa-solid fa-building text-[11px]"></i>
                                </span>
                                <span className="min-w-0 flex-1">
                                    <span className="block text-xs font-bold truncate">{client.name}</span>
                                    <span className="block text-[10px] text-neutral-500 truncate">{client.contactPerson || client.phone || client.email || 'Fiche client'}</span>
                                </span>
                                {String(clientId) === String(client.id) && <i className="fa-solid fa-check text-brand-600 text-xs"></i>}
                            </button>
                        ))}

                        {canCreate && (
                            <button
                                type="button"
                                role="option"
                                aria-selected={highlightedIndex === filteredClients.length}
                                onMouseEnter={() => setHighlightedIndex(filteredClients.length)}
                                onClick={requestCreate}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 text-brand-700 transition-colors ${highlightedIndex === filteredClients.length ? 'bg-brand-50' : 'hover:bg-brand-50/60'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-brand-100 text-brand-700 flex items-center justify-center shrink-0">
                                    <i className="fa-solid fa-plus text-[11px]"></i>
                                </span>
                                <span className="text-xs font-bold truncate">Créer « {query.trim()} »</span>
                            </button>
                        )}

                        {filteredClients.length === 0 && !canCreate && (
                            <div className="px-3 py-4 text-center text-[11px] text-neutral-500">
                                <i className="fa-solid fa-user-slash text-neutral-300 text-lg mb-1.5 block"></i>
                                Aucun client correspondant.
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}

// Même interaction que le client : un projet existant est sélectionnable
// directement depuis le devis, ou créé depuis la recherche s'il n'existe pas.
function ProjectCombobox({
    value = '',
    projectId = null,
    projects = [],
    clientId = null,
    clientName = '',
    onChange,
    onSelectProject,
    onRequestCreate,
    disabled = false
}) {
    const [query, setQuery] = useState(value || '');
    const [isOpen, setIsOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(0);
    const rootRef = useRef(null);
    const mobileSearchRef = useRef(null);

    // Distingue « l'utilisateur vient de taper ici » de « ce texte est resté
    // affiché ». Sans cette distinction, committer la saisie au clic extérieur
    // re-committerait aussi un libellé simplement hérité d'une sélection
    // précédente — et rendrait impossible l'effacement du chantier quand on
    // change de client (le parent remet projectRef à '', on le réécrirait
    // aussitôt). Remis à false dès que le parent impose une valeur.
    const saisieUtilisateurProjet = useRef(false);
    useEffect(() => { saisieUtilisateurProjet.current = false; setQuery(value || ''); }, [value]);
    // Focus du champ de la page plein écran sur téléphone — voir ClientCombobox.
    useEffect(() => {
        if (!isOpen || typeof window === 'undefined' || !window.matchMedia('(max-width: 480px)').matches) return;
        const timer = window.setTimeout(() => mobileSearchRef.current?.focus({ preventScroll: true }), 30);
        return () => window.clearTimeout(timer);
    }, [isOpen]);
    // Audit UX (2026-08-31) — le champ Projet perdait TOUJOURS ce qu'on y
    // tapait. Deux défauts cumulés, tous deux absents du champ Client :
    //
    //   1. La restauration est ici INCONDITIONNELLE : tout clic ailleurs
    //      réécrivait le champ, sans jamais committer la saisie. Le correctif
    //      P3 du 2026-08-30, qui avait ajouté au champ Client la conservation
    //      du texte libre non confirmé, n'a jamais été porté ici — un nom de
    //      chantier tapé puis non choisi dans la liste disparaissait en
    //      silence, et n'atteignait ni le devis ni le PDF.
    //   2. `value` était lu dans la fermeture du premier rendu (useEffect à
    //      dépendances []), donc la restauration rendait la valeur du montage.
    //
    // Ce ref, rafraîchi à chaque rendu, corrige (2) ; les branches ci-dessous
    // alignent (1) sur le comportement du champ Client.
    const dernieresValeursProjet = useRef({ query, value, projects, onChange, onSelectProject, clientId, clientName });
    dernieresValeursProjet.current = { query, value, projects, onChange, onSelectProject, clientId, clientName };
    const restoreCommittedProject = () => setQuery(dernieresValeursProjet.current.value || '');
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (rootRef.current && !rootRef.current.contains(event.target)) {
                const { query: q, value: committedValue, projects: ps, onChange: change, onSelectProject: selectProjectFn,
                        clientId: cid, clientName: cname } = dernieresValeursProjet.current;
                const trimmed = q.trim();
                const committedTrimmed = (committedValue || '').trim();
                // On ne rapproche que des affaires du client courant : deux
                // chantiers peuvent porter le même nom chez deux clients.
                const candidats = ps.filter(pr => !cid || pr.clientId === cid || (cname && pr.clientName === cname));
                const matched = candidats.find(pr => normalizeSearchText(pr.name) === normalizeSearchText(trimmed));
                const aTape = saisieUtilisateurProjet.current;
                if (aTape && trimmed && trimmed !== committedTrimmed && matched) {
                    selectProjectFn?.(matched);
                } else if (aTape && trimmed && trimmed !== committedTrimmed) {
                    change?.({ projectRef: trimmed, projectId: null });
                } else {
                    setQuery(committedValue || '');
                }
                saisieUtilisateurProjet.current = false;
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const projectsForClient = projects.filter(project =>
        !clientId || project.clientId === clientId || (clientName && project.clientName === clientName)
    );
    const normalizedQuery = normalizeSearchText(query.trim());
    const filteredProjects = projectsForClient.filter(project => {
        if (!normalizedQuery) return true;
        return [project.name, project.code, project.siteAddress, project.city]
            .filter(Boolean)
            .some(valueToSearch => normalizeSearchText(valueToSearch).includes(normalizedQuery));
    }).slice(0, 8);
    const exactProject = projectsForClient.find(project => normalizeSearchText(project.name) === normalizedQuery);
    const canCreate = Boolean(normalizedQuery && !exactProject);
    const optionCount = filteredProjects.length + (canCreate ? 1 : 0);

    useEffect(() => setHighlightedIndex(0), [normalizedQuery, clientId]);

    const selectProject = (project) => {
        setQuery(project.name || '');
        setIsOpen(false);
        onSelectProject?.(project);
    };

    const requestCreate = () => {
        const initialName = query.trim();
        if (!initialName) return;
        setIsOpen(false);
        onRequestCreate?.(initialName, clientId, clientName);
    };

    const handleKeyDown = (event) => {
        if (event.key === 'Escape') {
            event.stopPropagation();
            restoreCommittedProject();
            setIsOpen(false);
            return;
        }
        if (!isOpen && ['ArrowDown', 'Enter'].includes(event.key)) {
            event.preventDefault();
            setIsOpen(true);
            return;
        }
        if (!isOpen) return;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlightedIndex(index => Math.min(index + 1, Math.max(0, optionCount - 1)));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlightedIndex(index => Math.max(0, index - 1));
        } else if (event.key === 'Enter') {
            event.preventDefault();
            if (highlightedIndex < filteredProjects.length) selectProject(filteredProjects[highlightedIndex]);
            else if (canCreate) requestCreate();
        }
    };

    return (
        <div ref={rootRef} className="relative flex-1 min-w-0">
            <div className={`relative ${isOpen ? 'z-[101]' : ''}`}>
                <i className="fa-solid fa-helmet-safety absolute left-3 sm:left-3.5 top-1/2 -translate-y-1/2 text-neutral-500 text-[11px] pointer-events-none" aria-hidden="true"></i>
                <input
                    type="text"
                    value={query}
                    disabled={disabled}
                    // Audit UX (2026-08-31) — `onFocus` ouvrait la liste : en
                    // navigation clavier, chaque passage sur ce champ déployait un
                    // panneau qui recouvrait le titre du lot et une partie du
                    // tableau. Le clic et la frappe suffisent à exprimer
                    // l'intention d'ouvrir ; traverser le champ ne l'exprime pas.
                    onClick={() => setIsOpen(true)}
                    onChange={(event) => {
                        const nextQuery = event.target.value;
                        saisieUtilisateurProjet.current = true;
                        setQuery(nextQuery);
                        setIsOpen(true);
                    }}
                    onKeyDown={handleKeyDown}
                    placeholder="Projet"
                    className={`w-full bg-neutral-50 hover:bg-white focus:bg-white border rounded-xl sm:rounded-lg pl-9 sm:pl-10 pr-9 sm:pr-8 py-2.5 sm:py-1.5 text-xs font-bold text-neutral-900 placeholder-neutral-500 outline-none transition-all truncate ${isOpen ? 'border-brand-500 ring-2 ring-brand-500/10 bg-brand-50/50' : 'border-neutral-200'} ${disabled ? 'opacity-60 cursor-not-allowed' : ''}`}
                    aria-label="Projet du devis"
                    aria-autocomplete="list"
                    aria-controls="quote-project-listbox"
                    aria-expanded={isOpen}
                    aria-haspopup="listbox"
                    role="combobox"
                />
                {query && !disabled && (
                    <button
                        type="button"
                        onClick={() => { setQuery(''); onChange?.({ projectRef: '', projectId: null }); setIsOpen(true); }}
                        className="champ-effacer absolute right-2 top-1/2 -translate-y-1/2 text-neutral-500 hover:text-neutral-700 w-5 h-5 rounded-full hover:bg-neutral-100"
                        aria-label="Effacer le projet"
                    >
                        <i className="fa-solid fa-xmark text-[10px]"></i>
                    </button>
                )}
                {!query && (
                    // sm:hidden porté par le <span>, jamais par le <i> : Font Awesome
                    // (chargé APRÈS tailwind.css) impose `display: inline-block` à
                    // .fa-solid et gagne à spécificité égale — posé sur l'icône,
                    // `hidden` resterait sans effet et le chevron s'afficherait aussi
                    // sur desktop. Même piège que .btn-icon / .btn-primary.
                    <span className="sm:hidden absolute right-3 top-1/2 -translate-y-1/2 text-neutral-300 text-[10px] pointer-events-none" aria-hidden="true">
                        <i className="fa-solid fa-chevron-right"></i>
                    </span>
                )}
            </div>

            {isOpen && !disabled && (
                <div id="quote-project-listbox" role="listbox" className="picker-popover absolute left-0 right-0 top-full mt-1.5 bg-white border border-neutral-200 rounded-xl shadow-floating overflow-hidden z-[100] animate-fade-in">
                    <div className="picker-mobile-header">
                        <button
                            type="button"
                            onClick={() => { restoreCommittedProject(); setIsOpen(false); }}
                            className="picker-mobile-back"
                            aria-label="Retour au devis"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                        <div className="min-w-0 flex-1">
                            <p className="text-sm font-bold text-neutral-900 truncate">Choisir un projet</p>
                            <p className="text-[11px] text-neutral-500 truncate">Recherchez un chantier ou créez-en un</p>
                        </div>
                        {query && (
                            <button
                                type="button"
                                onClick={() => setQuery('')}
                                className="picker-mobile-clear"
                                aria-label="Effacer la recherche"
                            >
                                Effacer
                            </button>
                        )}
                    </div>
                    <div className="picker-mobile-search">
                        <i className="fa-solid fa-magnifying-glass"></i>
                        <input
                            ref={mobileSearchRef}
                            type="text"
                            value={query}
                            onChange={(event) => { saisieUtilisateurProjet.current = true; setQuery(event.target.value); setIsOpen(true); }}
                            onKeyDown={handleKeyDown}
                            placeholder="Rechercher un projet…"
                            aria-label="Rechercher un projet"
                        />
                    </div>
                    <div className="picker-popover-label px-3 pt-2.5 pb-1.5 text-[10px] font-bold uppercase tracking-wider text-neutral-500">
                        {normalizedQuery ? 'Projets correspondants' : (clientId ? 'Projets de ce client' : 'Projets récents')}
                    </div>
                    <div className="picker-results max-h-56 overflow-y-auto custom-scroll p-1.5">
                        {filteredProjects.map((project, index) => (
                            <button
                                key={project.id || project.name}
                                type="button"
                                role="option"
                                aria-selected={String(projectId) === String(project.id)}
                                onMouseEnter={() => setHighlightedIndex(index)}
                                onClick={() => selectProject(project)}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 transition-colors ${highlightedIndex === index ? 'bg-brand-50 text-brand-900' : 'text-neutral-700 hover:bg-neutral-50'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-neutral-100 text-neutral-500 flex items-center justify-center shrink-0">
                                    <i className="fa-solid fa-helmet-safety text-[11px]"></i>
                                </span>
                                <span className="min-w-0 flex-1">
                                    <span className="block text-xs font-bold truncate">{project.name}</span>
                                    <span className="block text-[10px] text-neutral-500 truncate">{[project.code, project.clientName, project.city].filter(Boolean).join(' · ') || 'Chantier'}</span>
                                </span>
                                {String(projectId) === String(project.id) && <i className="fa-solid fa-check text-brand-600 text-xs"></i>}
                            </button>
                        ))}

                        {canCreate && (
                            <button
                                type="button"
                                role="option"
                                aria-selected={highlightedIndex === filteredProjects.length}
                                onMouseEnter={() => setHighlightedIndex(filteredProjects.length)}
                                onClick={requestCreate}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 text-brand-700 transition-colors ${highlightedIndex === filteredProjects.length ? 'bg-brand-50' : 'hover:bg-brand-50/60'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-brand-100 text-brand-700 flex items-center justify-center shrink-0">
                                    <i className="fa-solid fa-plus text-[11px]"></i>
                                </span>
                                <span className="text-xs font-bold truncate">Créer le projet « {query.trim()} »</span>
                            </button>
                        )}

                        {filteredProjects.length === 0 && !canCreate && (
                            <div className="px-3 py-4 text-center text-[11px] text-neutral-500">Aucun projet correspondant.</div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}

// Même langage d'interaction que ClientCombobox, adapté au catalogue métier.
// La ligne de recherche vit dans le tableau : elle devient le point d'entrée
// naturel pour ajouter un ouvrage sans ouvrir une modale à chaque ligne.
function SolutionCombobox({
    solutions = [],
    onSelectSolution,
    onCreateSolution,
    placeholder = 'Rechercher un ouvrage à ajouter…'
}) {
    const [query, setQuery] = useState('');
    const [isOpen, setIsOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(0);
    const rootRef = useRef(null);
    const mobileSearchRef = useRef(null);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (rootRef.current && !rootRef.current.contains(event.target)) setIsOpen(false);
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const normalizedQuery = normalizeSearchText(query.trim());
    const filteredSolutions = solutions.filter(solution => {
        if (!normalizedQuery) return true;
        return [solution.name, solution.reference, solution.code, ...(solution.keywords || [])]
            .filter(Boolean)
            .some(valueToSearch => normalizeSearchText(valueToSearch).includes(normalizedQuery));
    }).slice(0, 8);
    const exactSolution = solutions.find(solution => normalizeSearchText(solution.name) === normalizedQuery);
    const canCreate = Boolean(normalizedQuery && !exactSolution);
    const optionCount = filteredSolutions.length + (canCreate ? 1 : 0);

    useEffect(() => setHighlightedIndex(0), [normalizedQuery]);

    // Sur smartphone, la liste devient une vue plein écran. Le champ de
    // recherche de cette vue doit récupérer le focus immédiatement, sinon
    // Safari conserve le focus sur le champ situé derrière le panneau et
    // déclenche un zoom ou un défilement inattendu.
    useEffect(() => {
        if (!isOpen || typeof window === 'undefined' || !window.matchMedia('(max-width: 767px)').matches) return;
        const timer = window.setTimeout(() => mobileSearchRef.current?.focus({ preventScroll: true }), 30);
        return () => window.clearTimeout(timer);
    }, [isOpen]);

    const selectSolution = (solution) => {
        setQuery('');
        setIsOpen(false);
        onSelectSolution?.(solution);
    };

    const createSolution = () => {
        const name = query.trim();
        if (!name) return;
        setQuery('');
        setIsOpen(false);
        onCreateSolution?.(name);
    };

    const handleKeyDown = (event) => {
        if (event.key === 'Escape') {
            event.stopPropagation();
            setIsOpen(false);
            return;
        }
        if (!isOpen && ['ArrowDown', 'Enter'].includes(event.key)) {
            event.preventDefault();
            setIsOpen(true);
            return;
        }
        if (!isOpen) return;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlightedIndex(index => Math.min(index + 1, Math.max(0, optionCount - 1)));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlightedIndex(index => Math.max(0, index - 1));
        } else if (event.key === 'Enter') {
            event.preventDefault();
            if (highlightedIndex < filteredSolutions.length) selectSolution(filteredSolutions[highlightedIndex]);
            else if (canCreate) createSolution();
        }
    };

    return (
        <div ref={rootRef} className="relative w-full">
            <div className={`relative ${isOpen ? 'z-[101]' : ''}`}>
                <i className="fa-solid fa-magnifying-glass absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-500 text-xs pointer-events-none"></i>
                <input
                    type="text"
                    value={query}
                    onFocus={() => setIsOpen(true)}
                    onChange={event => { setQuery(event.target.value); setIsOpen(true); }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    className={`w-full bg-white border rounded-xl pl-9 pr-10 py-2.5 text-xs font-semibold text-neutral-900 placeholder-neutral-400 outline-none transition-all ${isOpen ? 'border-brand-500 ring-2 ring-brand-500/10' : 'border-neutral-200 hover:border-neutral-300'}`}
                    aria-label="Rechercher un ouvrage à ajouter"
                    aria-autocomplete="list"
                    aria-controls="quote-solution-listbox"
                    aria-expanded={isOpen}
                    aria-haspopup="listbox"
                    role="combobox"
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-bold text-neutral-500 pointer-events-none">↵</span>
            </div>

            {isOpen && (
                <div id="quote-solution-listbox" role="listbox" className="picker-popover absolute left-0 right-0 top-full mt-1.5 bg-white border border-neutral-200 rounded-xl shadow-floating overflow-hidden z-[100] animate-fade-in">
                    <div className="picker-mobile-header">
                        <button
                            type="button"
                            onClick={() => setIsOpen(false)}
                            className="picker-mobile-back"
                            aria-label="Retour au devis"
                        >
                            <i className="fa-solid fa-arrow-left"></i>
                        </button>
                        <div className="min-w-0 flex-1">
                            <p className="text-sm font-bold text-neutral-900 truncate">Ajouter un ouvrage</p>
                            <p className="text-[11px] text-neutral-500 truncate">Choisissez une prestation dans le catalogue</p>
                        </div>
                        {query && (
                            <button
                                type="button"
                                onClick={() => setQuery('')}
                                className="picker-mobile-clear"
                                aria-label="Effacer la recherche"
                            >
                                Effacer
                            </button>
                        )}
                    </div>
                    <div className="picker-mobile-search">
                        <i className="fa-solid fa-magnifying-glass"></i>
                        <input
                            ref={mobileSearchRef}
                            type="text"
                            value={query}
                            onChange={event => { setQuery(event.target.value); setIsOpen(true); }}
                            onKeyDown={handleKeyDown}
                            placeholder="Rechercher un ouvrage…"
                            aria-label="Rechercher un ouvrage dans le catalogue"
                        />
                    </div>
                    <div className="picker-popover-label px-3 pt-2.5 pb-1.5 text-[10px] font-bold uppercase tracking-wider text-neutral-500">
                        {normalizedQuery ? 'Ouvrages correspondants' : 'Ouvrages récents et favoris'}
                    </div>
                    <div data-testid="quote-solution-scroll" className="picker-results max-h-[9.5rem] overflow-y-auto custom-scroll p-1.5">
                        {filteredSolutions.map((solution, index) => (
                            <button
                                key={solution.id || solution.name}
                                type="button"
                                role="option"
                                aria-selected={false}
                                onMouseEnter={() => setHighlightedIndex(index)}
                                onClick={() => selectSolution(solution)}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 transition-colors ${highlightedIndex === index ? 'bg-brand-50 text-brand-900' : 'text-neutral-700 hover:bg-neutral-50'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-neutral-100 text-neutral-500 flex items-center justify-center shrink-0">
                                    <i className={`fa-solid ${solution.icon || 'fa-cube'} text-[11px]`}></i>
                                </span>
                                <span className="min-w-0 flex-1">
                                    <span className="block text-xs font-bold truncate">{solution.name}</span>
                                    <span className="block text-[10px] text-neutral-600 truncate">{solution.reference || solution.code || libelleModes(solution.allowedModes)}</span>
                                </span>
                                <i className="fa-solid fa-arrow-right text-[10px] text-neutral-300"></i>
                            </button>
                        ))}

                        {canCreate && (
                            <button
                                type="button"
                                role="option"
                                aria-selected={highlightedIndex === filteredSolutions.length}
                                onMouseEnter={() => setHighlightedIndex(filteredSolutions.length)}
                                onClick={createSolution}
                                className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center gap-2.5 text-brand-700 transition-colors ${highlightedIndex === filteredSolutions.length ? 'bg-brand-50' : 'hover:bg-brand-50/60'}`}
                            >
                                <span className="w-7 h-7 rounded-lg bg-brand-100 text-brand-700 flex items-center justify-center shrink-0">
                                    <i className="fa-solid fa-plus text-[11px]"></i>
                                </span>
                                <span className="text-xs font-bold truncate">Créer « {query.trim()} »</span>
                            </button>
                        )}

                        {filteredSolutions.length === 0 && !canCreate && (
                            <div className="px-3 py-4 text-center text-[11px] text-neutral-500">
                                <i className="fa-solid fa-cube text-neutral-300 text-lg mb-1.5 block"></i>
                                Aucun ouvrage correspondant.
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}

// ═══════════════════════════════════════════════════════════════
// BLOC 3/10 : MOTEUR UNIVERSEL DE MÉTRÉ, UNITÉS & AST SÉCURISÉ (ZERO new Function)
// ═══════════════════════════════════════════════════════════════

class ErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null };
    }
    static getDerivedStateFromError(error) {
        return { hasError: true, error };
    }
    componentDidCatch(error, errorInfo) {
        console.error("[ikadevis ErrorBoundary]", error, errorInfo);
    }
    render() {
        if (this.state.hasError) {
            return (
                <div className="min-h-screen flex items-center justify-center bg-neutral-900 text-white p-6 font-sans">
                    <div className="max-w-md w-full bg-neutral-800 border border-neutral-700 rounded-3xl p-8 text-center shadow-2xl space-y-5">
                        <div className="w-16 h-16 rounded-2xl bg-red-500/20 text-red-400 flex items-center justify-center mx-auto text-2xl border border-red-500/30">
                            <i className="fa-solid fa-shield-halved"></i>
                        </div>
                        <div>
                            <h2 className="text-xl font-semibold text-white">Récupération Sécurisée d'Affichage</h2>
                            <p className="text-xs text-neutral-500 mt-1">Vos données de devis et catalogue restent sauvegardées.</p>
                        </div>
                        <p className="text-xs text-red-300 font-mono bg-neutral-950/80 p-3 rounded-xl text-left overflow-auto max-h-32 border border-neutral-800">
                            {this.state.error?.message || "Erreur interceptée"}
                        </p>
                        <button onClick={() => window.location.reload()} className="btn-primary w-full py-3.5 shadow-lg font-bold">
                            <i className="fa-solid fa-arrow-rotate-right mr-2"></i>Actualiser l'application
                        </button>
                    </div>
                </div>
            );
        }
        return this.props.children;
    }
}


